const neGlyphFiltBtn = `<button type="button" class="gt-b gt-flt" aria-pressed="false" aria-label="filter cells" title="filter · veil the cells that do not meet your conditions ( f )"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M10 20a1 1 0 0 0 .553.895l2 1A1 1 0 0 0 14 21v-7a2 2 0 0 1 .517-1.341L21.74 4.67A1 1 0 0 0 21 3H3a1 1 0 0 0-.742 1.67l7.225 7.989A2 2 0 0 1 10 14z"/></svg><span class="gt-t">filter</span></button>`

